/*
If you want to aim high, aim high
Don't let that studying and grades consume you
Just live life young
******************************
If I'm the sun, you're the moon
Because when I go up, you go down
*******************************
I'm working for the day I will surpass you
https://www.a2oj.com/Ladder16.html
*/
import java.util.*;
import java.io.*;
import java.math.*;

public class E {
    private static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split("\\s+");
        long N = Long.parseLong(input[0]);
        long M = Long.parseLong(input[1]);
        long L = Long.parseLong(input[2]);
        long R = Long.parseLong(input[3]);

        long total = N * M;
        long range = R - L + 1;

        if (total % 2 == 1) {
            BigInteger base = BigInteger.valueOf(range);
            BigInteger exp = BigInteger.valueOf(total);
            BigInteger mod = BigInteger.valueOf(MOD);
            long result = base.modPow(exp, mod).longValue();
            System.out.println((result + MOD) % MOD);
        } else {
            BigInteger base = BigInteger.valueOf(range);
            BigInteger exp = BigInteger.valueOf(total);
            BigInteger mod = BigInteger.valueOf(MOD);
            long result = base.modPow(exp, mod).longValue();

            if ((R - L) % 2 == 0) {
                result = (result + 1) % MOD;
            }

            long inv2 = modPow(2, MOD - 2, MOD);
            result = (int) ((result * inv2) % MOD);
            System.out.println(result);
        }
    }

    private static long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
